                        dashboard: dashboard,
                        tags: ['cyclotron-examples'],
                        description: dashboard.description,
                        lastUpdatedBy: user._id,
                        deleted: false,
                        editors: [user],
                        viewers: [],
                        rev: 1
                    }
                }, { upsert: true }, function (err, dashboard) {
                    revisionModel.remove({ name: name }).exec();
                    console.log('Wrote ' + name);
                });
            });
    }
});

