var config = require('../config/config'),
    _ = require('lodash'),
    moment = require('moment'),
    mongoose = require('mongoose'),
    api = require('./api');

var DataBuckets = mongoose.model('databucket');

exports.get = function (req, res) {
    DataBuckets
        .find()
        .select('-data')
        .exec(_.wrap(res, api.getCallback));
};

